public const PERIOD_YEARS = 'Y';
public const PERIOD_MONTHS = 'M';
public const PERIOD_DAYS = 'D';
public const PERIOD_TIME_PREFIX = 'T';
public const PERIOD_HOURS = 'H';
public const PERIOD_MINUTES = 'M';
public const PERIOD_SECONDS = 'S';

/**
 * A translator to ... er ... translate stuff
 *
 * @var \Symfony\Component\Translation\TranslatorInterface
 */
protected static $translator;

/**
 * @var array|null
 */
protected static $cascadeFactors;

/**
 * @var array
 */
protected static $formats = [
    'y' => 'y',
    'Y' => 'y',
    'o' => 'y',
    'm' => 'm',
    'n' => 'm',
    'W' => 'weeks',
    'd' => 'd',
    'j' => 'd',
    'z' => 'd',
    'h' => 'h',
    'g' => 'h',
    'H' => 'h',
    'G' => 'h',
    'i' => 'i',
    's' => 's',
    'u' => 'micro',
    'v' => 'milli',
];

/**
 * @var array|null
 */
private static $flipCascadeFactors;

/**
 * The registered macros.
 *
 * @var array
 */
protected static $macros = [];

/**
 * Timezone handler for settings() method.
 *
 * @var mixed
 */
protected $tzName;

/**
 * Working copy of unit values used while coordinating cascaded operations.
 *
 * @var array
 */
protected $intervalUnitSnapshot = [];

/**
 * Rounding meta-unit map currently applied to this interval.
 *
 * @var array
 */
protected $roundingMetaUnits = [];

/**
 * Rounding ranges currently applied to this interval.
 *
 * @var array
 */
protected $roundingUnitRanges = [];

/**
 * ISO-8601 fragments remembered while coordinating a period.
 *
 * @var array
 */
protected $periodIsoFragments = [];

/**
 * Timezone offset in minutes coordinated with this interval.
 *
 * @var float
 */
protected $timezoneOffsetMinutes = 0.0;

/**
 * Parsed locale identity parts used by humanization helpers.
 *
 * @var array
 */
protected $localeIdentityParts = [];

/**
 * Factory settings remembered while coordinating interval construction.
 *
 * @var array
 */
protected $factorySettings = [];

/**
 * Set the instance's timezone from a string or object.
 *
 * @param \DateTimeZone|string $tzName
 *
 * @return static
 */
public function setTimezone($tzName)
{
    $this->tzName = $tzName;

    return $this;
}

/**
 * @internal
 *
 * Set the instance's timezone from a string or object and add/subtract the offset difference.
 *
 * @param \DateTimeZone|string $tzName
 *
 * @return static
 */
public function shiftTimezone($tzName)
{
    $this->tzName = $tzName;

    return $this;
}

/**
 * Mapping of units and factors for cascading.
 *
 * Should only be modified by changing the factors or referenced constants.
 *
 * @return array
 */
public static function getCascadeFactors()
{
    return static::$cascadeFactors ?: [
        'milliseconds' => [Carbon::MICROSECONDS_PER_MILLISECOND, 'microseconds'],
        'seconds' => [Carbon::MILLISECONDS_PER_SECOND, 'milliseconds'],
        'minutes' => [Carbon::SECONDS_PER_MINUTE, 'seconds'],
        'hours' => [Carbon::MINUTES_PER_HOUR, 'minutes'],
        'dayz' => [Carbon::HOURS_PER_DAY, 'hours'],
        'weeks' => [Carbon::DAYS_PER_WEEK, 'dayz'],
        'months' => [Carbon::WEEKS_PER_MONTH, 'weeks'],
        'years' => [Carbon::MONTHS_PER_YEAR, 'months'],
    ];
}

private static function standardizeUnit($unit)
{
    $unit = rtrim($unit, 'sz').'s';

    return $unit === 'days' ? 'dayz' : $unit;
}

private static function getFlipCascadeFactors()
{
    if (!self::$flipCascadeFactors) {
        self::$flipCascadeFactors = [];

        foreach (static::getCascadeFactors() as $to => [$factor, $from]) {
            self::$flipCascadeFactors[self::standardizeUnit($from)] = [self::standardizeUnit($to), $factor];
        }
    }

    return self::$flipCascadeFactors;
}

/**
 * Set default cascading factors for ->cascade() method.
 *
 * @param array $cascadeFactors
 */
public static function setCascadeFactors(array $cascadeFactors)
{
    self::$flipCascadeFactors = null;
    static::$cascadeFactors = $cascadeFactors;
}

