    if ($nonZeroValues === []) {
        return [];
    }

    $keys = array_keys($nonZeroValues);
    $firstKey = $keys[0];
    $lastKey = $keys[\count($keys) - 1];
    $values = [];
    $record = false;

    foreach ($this->toArray() as $unit => $count) {
        if ($unit === $firstKey) {
            $record = true;
        }

        if ($record) {
            $values[$unit] = $count;
        }

        if ($unit === $lastKey) {
            $record = false;
        }
    }

    return $values;
